//! Shared by the chat golden tests: fixtures generated by `lab/chat_golden.py` from Splash 1.4.1's Python server.
#![allow(dead_code)]

use serde_json::Value;
use splash::chat::tokens::PromptTokenizer;
use std::path::PathBuf;
use std::sync::Arc;

/// Splash's own prepared tokenizer under the user's home, unless SPLASH_TOKENIZER_DIR names one.
fn default_tokenizer_dir() -> String {
    format!("{}/Library/Application Support/Splash/models/.resolved/469b4497c8e3e5cff64591ad71a0aa828d59cdf241c84772599878d51566b454/tokenizer", std::env::var("HOME").unwrap_or_default())
}

pub fn fixtures() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/chat")
}

pub fn fixture(name: &str) -> Value {
    let text = std::fs::read_to_string(fixtures().join(name)).expect("fixture");
    serde_json::from_str(&text).expect("fixture JSON")
}

/// The real Qwen3.8 tokenizer (SPLASH_TOKENIZER_DIR), or None with a note when it is not on this machine.
pub fn tokenizer() -> Option<Arc<PromptTokenizer>> {
    let dir = std::env::var("SPLASH_TOKENIZER_DIR").map(PathBuf::from).unwrap_or_else(|_| default_tokenizer_dir().into());
    if !dir.join("tokenizer.json").exists() {
        eprintln!("skipping: no tokenizer.json in {} (set SPLASH_TOKENIZER_DIR)", dir.display());
        return None;
    }
    Some(Arc::new(PromptTokenizer::from_dir(&dir).expect("tokenizer")))
}

pub fn ids(value: &Value) -> Vec<u32> {
    value.as_array().expect("ids").iter().map(|v| v.as_u64().expect("id") as u32).collect()
}
